    adcs x26, x23, x11
    umov x23, v15.d[0]
    extr x11, x16, x21, #52
    adcs x21, x23, x11
    umov x23, v27.d[0]
    extr x11, x24, x16, #52
    adcs x16, x23, x11
    umov x23, v13.d[0]
    extr x11, x22, x24, #52
    adc x24, x23, x11
    adds x20, x8, x20
    lsl x11, x8, #4
    adcs x27, x12, x27
    adcs x10, x3, x10
    adcs x15, x4, x15
    adcs x14, x5, x14
    adcs x19, x13, x19
    adcs x6, x7, x6
    adcs x9, x26, x9
    adcs x22, x21, x28
    adcs x25, x16, x25
    adc x23, x24, x17
    adds x20, x20, x11
    extr x11, x12, x8, #60
    adcs x27, x27, x11
    extr x11, x3, x12, #60
    adcs x10, x10, x11
    extr x11, x4, x3, #60
    adcs x15, x15, x11
    extr x11, x5, x4, #60
    adcs x14, x14, x11
    extr x11, x13, x5, #60
    adcs x19, x19, x11
    extr x11, x7, x13, #60
    adcs x6, x6, x11
    extr x11, x26, x7, #60
    adcs x9, x9, x11
    extr x11, x21, x26, #60
    adcs x22, x22, x11
    extr x11, x16, x21, #60
    adcs x25, x25, x11
    extr x11, x24, x16, #60
    adc x23, x23, x11
    umov x11, v0.d[0]
    adds x20, x11, x20
    umov x11, v0.d[1]
    adcs x27, x11, x27
    umov x11, v1.d[0]
    adcs x10, x11, x10
    umov x11, v1.d[1]
    adcs x15, x11, x15
    umov x11, v2.d[0]
    adcs x14, x11, x14
    umov x11, v2.d[1]
    adcs x19, x11, x19
    umov x11, v3.d[0]
    adcs x6, x11, x6
    umov x11, v3.d[1]
    adcs x9, x11, x9
    umov x11, v4.d[0]
    adcs x22, x11, x22
    umov x11, v4.d[1]
    adcs x16, x11, x25
    umov x11, v5.d[0]
    adc x24, x11, x23
    and x11, x20, #0xffffffffff
    add x11, x11, x11, lsl         #4
    lsl x23, x11, #48
    lsr x25, x11, #16
    extr x11, x27, x20, #40
    adds x20, x11, #1
    extr x11, x10, x27, #40
    adcs x27, x11, xzr
    extr x11, x15, x10, #40
    adcs x10, x11, xzr
    extr x11, x14, x15, #40
    adcs x15, x11, xzr
    extr x11, x19, x14, #40
    adcs x14, x11, xzr
    extr x11, x6, x19, #40
    adcs x19, x11, xzr
    extr x11, x9, x6, #40
    adcs x6, x11, xzr
    extr x11, x22, x9, #40
    adcs x9, x11, xzr
    extr x11, x16, x22, #40
    adcs x22, x11, xzr
    extr x11, x24, x16, #40
    adcs x23, x11, x23
    mov x11, #0x11000000
    adc x24, x25, xzr
    cmp x24, x11
    csel x25, x11, xzr, cs
    sbcs x20, x20, xzr
    sbcs x27, x27, xzr
    sbcs x10, x10, xzr
    stp x20, x27, [x0, #88]
    sbcs x15, x15, xzr
    sbcs x14, x14, xzr
    stp x10, x15, [x0, #104]
    sbcs x19, x19, xzr
    sbcs x6, x6, xzr
    stp x14, x19, [x0, #120]
    sbcs x9, x9, xzr
    sbcs x22, x22, xzr
    stp x6, x9, [x0, #136]
    sbcs x23, x23, xzr
    sbc x11, x24, xzr
    stp x22, x23, [x0, #152]
    sub x11, x11, x25
    str x11, [x0, #168]
    ldp d14, d15, [sp, #128]
    ldp d12, d13, [sp, #112]
    ldp d10, d11, [sp, #96]
    ldp d8, d9, [sp, #80]
    ldp x27, x28, [sp, #64]
    ldp x25, x26, [sp, #48]
    ldp x23, x24, [sp, #32]
    ldp x21, x22, [sp, #16]
    ldp x19, x20, [sp], #144
    ret

//***********************************************************************
//  Squaring in GF(p^2), both components
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//  Inputs: a = [a1, a0] stored in [x1]
//  Output: c = [c1, c0] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+2p, then a1) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 88) holds s = a0+a1 (raw);
//         [sp+88 .. 176) holds t = 2*a0 (raw; self-add, EXTR is slow).
//***********************************************************************
.global fp2_sqr
.p2align 6
fp2_sqr:
    sub   sp, sp, #256               // 176 for s + t buffer + 80 for callee saves
    stp   x19, x20, [sp, #176]
    stp   x21, x22, [sp, #192]
    stp   x23, x24, [sp, #208]
    stp   x25, x26, [sp, #224]
    stp   x27, x28, [sp, #240]

    // t = 2*a0 (raw) -> [sp+88] ; a0 stays in x3..x13
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldr   x13, [x1, #80]
    adds  x14, x3, x3
    adcs  x15, x4, x4
    adcs  x16, x5, x5
    adcs  x17, x6, x6
    adcs  x19, x7, x7
    adcs  x20, x8, x8
    adcs  x21, x9, x9
    adcs  x22, x10, x10
    adcs  x23, x11, x11
    adcs  x24, x12, x12
    adc   x25, x13, x13
    stp   x14, x15, [sp, #88]
    stp   x16, x17, [sp, #104]
    stp   x19, x20, [sp, #120]
    stp   x21, x22, [sp, #136]
    stp   x23, x24, [sp, #152]
    str   x25, [sp, #168]
    // s = a0 + a1 (raw) -> [sp]
    ldp   x14, x15, [x1, #88]
    ldp   x16, x17, [x1, #104]
    ldp   x19, x20, [x1, #120]
    ldp   x21, x22, [x1, #136]
    ldp   x23, x24, [x1, #152]
    ldr   x25, [x1, #168]
    adds  x14, x14, x3
    adcs  x15, x4, x15
    adcs  x16, x5, x16
    adcs  x17, x6, x17
    adcs  x19, x7, x19
    adcs  x20, x8, x20
    adcs  x21, x9, x21
    adcs  x22, x10, x22
    adcs  x23, x11, x23
    adcs  x24, x12, x24
    adc   x25, x25, x13
    stp   x14, x15, [sp]
    stp   x16, x17, [sp, #16]
    stp   x19, x20, [sp, #32]
    stp   x21, x22, [sp, #48]
    stp   x23, x24, [sp, #64]
    str   x25, [sp, #80]
    // d = a0 - a1 + 2p (raw) -> x3..x13 ; p2 = 2p = {-2,-1,...,0x0000000021FFFFFF}
    ldp   x14, x15, [x1, #88]
    subs  x3, x3, x14
    sbcs  x4, x4, x15
    ldp   x14, x15, [x1, #104]
    sbcs  x5, x5, x14
    sbcs  x6, x6, x15
    ldp   x14, x15, [x1, #120]
    sbcs  x7, x7, x14
    sbcs  x8, x8, x15
    ldp   x14, x15, [x1, #136]
    sbcs  x9, x9, x14
    sbcs  x10, x10, x15
    ldp   x14, x15, [x1, #152]
    sbcs  x11, x11, x14
    sbcs  x12, x12, x15
    ldr   x14, [x1, #168]
    sbcs  x13, x13, x14
    mov   x14, #-2
    adds  x3, x3, x14
    mov   x14, #-1
    adcs  x4, x4, x14
    adcs  x5, x5, x14
    adcs  x6, x6, x14
    adcs  x7, x7, x14
    adcs  x8, x8, x14
    adcs  x9, x9, x14
    adcs  x10, x10, x14
    adcs  x11, x11, x14
    adcs  x12, x12, x14
    movz  x14, #0xffff
    movk  x14, #0x21ff, lsl #16      // 2p[10]
    adc   x13, x13, x14

    // [x14:x26] <- z = d x s0
    ldr   x27, [sp]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28

    // c0 -> [x0] (a0's slot; a1 is still intact if c == a)
    stp   x26, x14, [x0]
    stp   x15, x16, [x0, #16]
    stp   x17, x19, [x0, #32]
    stp   x20, x21, [x0, #48]
    stp   x22, x23, [x0, #64]
    str   x24, [x0, #80]

    // [x26, x14:x25] <- z = a1 x t0
    ldp   x3, x4, [x1, #88]
    ldp   x5, x6, [x1, #104]
    ldp   x7, x8, [x1, #120]
    ldp   x9, x10, [x1, #136]
    ldp   x11, x12, [x1, #152]
    ldr   x13, [x1, #168]
    add   x1, sp, #88                // x1 is dead after the a1 load: reuse it as the t pointer
    ldr   x27, [x1]
    MUL64x704  x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x27, x28

    stp   x25, x26, [x0, #88]
    stp   x14, x15, [x0, #104]
    stp   x16, x17, [x0, #120]
    stp   x19, x20, [x0, #136]
    stp   x21, x22, [x0, #152]
    str   x23, [x0, #168]
    ldp   x27, x28, [sp, #240]
    ldp   x25, x26, [sp, #224]
    ldp   x23, x24, [sp, #208]
    ldp   x21, x22, [sp, #192]
    ldp   x19, x20, [sp, #176]
    add   sp, sp, #256
    ret

//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global fp_mul
.p2align 6
fp_mul:
    stp   x19, x20, [sp, #-80]!
    stp   x21, x22, [sp, #16]
    stp   x23, x24, [sp, #32]
    stp   x25, x26, [sp, #48]
    stp   x27, x28, [sp, #64]
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldr   x13, [x1, #80]

    // [x14:x26] <- z = a x b0
    ldr   x27, [x2]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x2, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28

    stp   x26, x14, [x0]
    stp   x15, x16, [x0, #16]
    stp   x17, x19, [x0, #32]
    stp   x20, x21, [x0, #48]
    stp   x22, x23, [x0, #64]
    str   x24, [x0, #80]
    ldp   x27, x28, [sp, #64]
    ldp   x25, x26, [sp, #48]
    ldp   x23, x24, [sp, #32]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #80
    ret

.global fp_sqr
.p2align 6
fp_sqr:
    mov   x2, x1
    b     fp_mul
